#include <stdint.h>
#include <stdlib.h>
#include <string.h>

// Hungarian algorithm (Jonker-Volgenant style, O(n^3)) for square cost matrix.
// cost: n*n doubles, row-major. result: n int64, result[i] = assigned column for row i.
void hungarian(const double* cost, int64_t n, int64_t* result) {
    int64_t N = n;
    double* u = (double*)malloc((N+1)*sizeof(double));
    double* v = (double*)malloc((N+1)*sizeof(double));
    int64_t* p = (int64_t*)malloc((N+1)*sizeof(int64_t));
    int64_t* way = (int64_t*)malloc((N+1)*sizeof(int64_t));
    double* minv = (double*)malloc((N+1)*sizeof(double));
    unsigned char* used = (unsigned char*)malloc((N+1)*sizeof(unsigned char));
    for (int64_t i=0;i<=N;i++){ u[i]=0.0; v[i]=0.0; p[i]=0; way[i]=0; }
    const double INF = 1e300;
    for (int64_t i=1;i<=N;i++){
        p[0]=i;
        int64_t j0=0;
        for (int64_t j=0;j<=N;j++){ minv[j]=INF; used[j]=0; }
        while(1){
            used[j0]=1;
            int64_t i0=p[j0];
            double delta=INF;
            int64_t j1=0;
            const double* crow = cost + (i0-1)*N;
            for (int64_t j=1;j<=N;j++){
                if(!used[j]){
                    double cur = crow[j-1] - u[i0] - v[j];
                    if(cur < minv[j]){ minv[j]=cur; way[j]=j0; }
                    if(minv[j] < delta){ delta=minv[j]; j1=j; }
                }
            }
            for (int64_t j=0;j<=N;j++){
                if(used[j]){ u[p[j]] += delta; v[j] -= delta; }
                else { minv[j] -= delta; }
            }
            j0=j1;
            if(p[j0]==0) break;
        }
        while(1){
            int64_t j1=way[j0];
            p[j0]=p[j1];
            j0=j1;
            if(j0==0) break;
        }
    }
    for (int64_t j=1;j<=N;j++){
        result[p[j]-1] = j-1;
    }
    free(u); free(v); free(p); free(way); free(minv); free(used);
}
EOF
