#include <stdint.h>
#include <stdlib.h>
#include <string.h>

// Forward auction algorithm with epsilon scaling, integer costs.
// cost: n*n doubles row-major. result[i] = assigned column for row i.
void auction(const double* cost, int64_t n, int64_t* result) {
    int64_t N = n;
    const double S = 1e6;
    int64_t* c = (int64_t*)malloc(N*N*sizeof(int64_t));
    for (int64_t i=0;i<N*N;i++){ c[i] = (int64_t)llround(cost[i]*S); }
    int64_t* p = (int64_t*)calloc(N, sizeof(int64_t)); // prices
    int64_t* col_of_row = (int64_t*)malloc(N*sizeof(int64_t));
    int64_t* row_of_col = (int64_t*)malloc(N*sizeof(int64_t));
    int64_t* stack = (int64_t*)malloc(N*sizeof(int64_t));
    for (int64_t i=0;i<N;i++){ col_of_row[i]=-1; row_of_col[i]=-1; }

    int64_t maxc = 0;
    for (int64_t i=0;i<N*N;i++){ if(c[i]>maxc) maxc=c[i]; }
    int64_t eps = maxc;
    if (eps < 1) eps = 1;

    while (eps >= 1) {
        // reset assignment
        for (int64_t i=0;i<N;i++){ col_of_row[i]=-1; row_of_col[i]=-1; }
        int64_t top = N;
        for (int64_t i=0;i<N;i++){ stack[i]=i; }
        while (top > 0) {
            top--;
            int64_t i = stack[top];
            const int64_t* crow = c + i*N;
            int64_t best_j = -1, second_j = -1;
            int64_t best_val = INT64_MAX, second_val = INT64_MAX;
            for (int64_t j=0;j<N;j++){
                int64_t val = crow[j] + p[j];
                if (val < best_val) { second_val = best_val; second_j = best_j; best_val = val; best_j = j; }
                else if (val < second_val) { second_val = val; second_j = j; }
            }
            int64_t bid = second_val - best_val + eps;
            p[best_j] += bid;
            int64_t old = row_of_col[best_j];
            col_of_row[i] = best_j;
            row_of_col[best_j] = i;
            if (old != -1) {
                col_of_row[old] = -1;
                stack[top] = old;
                top++;
            }
        }
        eps = eps / 4;
    }
    for (int64_t i=0;i<N;i++){ result[i] = col_of_row[i]; }
    free(c); free(p); free(col_of_row); free(row_of_col); free(stack);
}
EOF
