void auctiond2(const double* cost, int64_t n, int64_t* result) {
    int64_t N = n;
    double* p = (double*)calloc(N, sizeof(double));
    int64_t* col_of_row = (int64_t*)malloc(N*sizeof(int64_t));
    int64_t* row_of_col = (int64_t*)malloc(N*sizeof(int64_t));
    int64_t* stack = (int64_t*)malloc(N*sizeof(int64_t));
    for (int64_t i=0;i<N;i++){ col_of_row[i]=-1; row_of_col[i]=-1; }

    double maxc = 0;
    for (int64_t i=0;i<N*N;i++){ if(cost[i]>maxc) maxc=cost[i]; }
    double eps = maxc;
    if (eps < 1.0) eps = 1.0;
    double eps_final = 1e-9;
    int64_t total_bids = 0;
    while (eps >= eps_final) {
        for (int64_t i=0;i<N;i++){ col_of_row[i]=-1; row_of_col[i]=-1; }
        int64_t top = N;
        for (int64_t i=0;i<N;i++){ stack[i]=i; }
        int64_t bids = 0;
        while (top > 0) {
            top--;
            int64_t i = stack[top];
            const double* crow = cost + i*N;
            int64_t best_j = -1;
            double best_val = 1e300, second_val = 1e300;
            for (int64_t j=0;j<N;j++){
                double val = crow[j] - p[j];
                if (val < best_val) { second_val = best_val; best_val = val; best_j = j; }
