            }
            double bid = second_val - best_val + eps;
            p[best_j] += bid;
            int64_t old = row_of_col[best_j];
            col_of_row[i] = best_j;
            row_of_col[best_j] = i;
            if (old != -1) {
                col_of_row[old] = -1;
                stack[top] = old;
                top++;
            }
            bids++;
            if (bids > 10000000) { fprintf(stderr, "TOO MANY BIDS\n"); break; }
        }
        total_bids += bids;
        eps /= 4.0;
    }
    for (int64_t i=0;i<N;i++){ result[i] = col_of_row[i]; }
    free(p); free(col_of_row); free(row_of_col); free(stack);
